/**
 * IVX Production Soak Test Monitor
 * Runs continuous health checks every 60 seconds.
 * Results stored to /tmp/ivx-soak-results.json
 */
import { writeFileSync, readFileSync, existsSync } from 'fs';

const API = 'https://ivx-holdings-platform.onrender.com';
const LANDING = 'https://ivxholding.com';
const INTERVAL_MS = 60_000;
const RESULTS_FILE = '/tmp/ivx-soak-results.json';

interface SoakResult {
  timestamp: string;
  healthStatus: string;
  healthHttpCode: number;
  healthTimeMs: number;
  databaseConfigured: boolean;
  aiOk: boolean;
  queueDepth: number;
  queue5xx: number;
  workerRunning: boolean;
  staleQueue: boolean;
  landingHttpCode: number;
  landingTimeMs: number;
  publicChatOk: boolean;
  publicChatTimeMs: number;
  error?: string;
}

interface SoakSummary {
  startTime: string;
  endTime: string | null;
  duration: string;
  requestCount: number;
  successCount: number;
  failureCount: number;
  errors4xx: number;
  errors5xx: number;
  timeouts: number;
  restarts: number;
  queueStalls: number;
  databaseFailures: number;
  providerFailures: number;
  p50: number;
  p95: number;
  p99: number;
  results: SoakResult[];
}

function loadSummary(): SoakSummary {
  if (existsSync(RESULTS_FILE)) {
    return JSON.parse(readFileSync(RESULTS_FILE, 'utf8'));
  }
  return {
    startTime: new Date().toISOString(),
    endTime: null,
    duration: '',
    requestCount: 0,
    successCount: 0,
    failureCount: 0,
    errors4xx: 0,
    errors5xx: 0,
    timeouts: 0,
    restarts: 0,
    queueStalls: 0,
    databaseFailures: 0,
    providerFailures: 0,
    p50: 0,
    p95: 0,
    p99: 0,
    results: [],
  };
}

async function checkOnce(): Promise<SoakResult> {
  const result: SoakResult = {
    timestamp: new Date().toISOString(),
    healthStatus: 'unknown',
    healthHttpCode: 0,
    healthTimeMs: 0,
    databaseConfigured: false,
    aiOk: false,
    queueDepth: 0,
    queue5xx: 0,
    workerRunning: false,
    staleQueue: false,
    landingHttpCode: 0,
    landingTimeMs: 0,
    publicChatOk: false,
    publicChatTimeMs: 0,
  };

  try {
    const hStart = Date.now();
    const hResp = await fetch(`${API}/health`, { signal: AbortSignal.timeout(15000) });
    result.healthHttpCode = hResp.status;
    result.healthTimeMs = Date.now() - hStart;
    if (hResp.ok) {
      const h = await hResp.json() as any;
      result.healthStatus = h.status || 'unknown';
      result.databaseConfigured = h.databaseConfigured === true;
      result.aiOk = h.ai?.ok === true;
      result.queueDepth = h.queue?.depth ?? 0;
      result.queue5xx = h.queue?.alerts5xx ?? 0;
      result.workerRunning = h.queue?.workerRunning === true;
      result.staleQueue = h.queue?.staleQueue === true;
    }
  } catch (e: any) {
    result.error = e.message;
    if (e.name === 'TimeoutError' || e.name === 'AbortError') result.healthHttpCode = -1;
  }

  try {
    const lStart = Date.now();
    const lResp = await fetch(LANDING, { signal: AbortSignal.timeout(15000), redirect: 'follow' });
    result.landingHttpCode = lResp.status;
